    20→package ids.messaging.core.daps.aisec;
    21→
    22→import java.io.IOException;
    23→import java.security.PrivateKey;
    24→import java.time.Instant;
    25→import java.util.Date;
    26→
    27→import de.fraunhofer.iais.eis.ConnectorDeployMode;
    28→import ids.messaging.core.config.ClientProvider;
    29→import ids.messaging.core.config.ConfigContainer;
    30→import ids.messaging.core.config.ssl.keystore.KeyStoreManager;
    31→import ids.messaging.core.config.util.ConnectorFingerprintProvider;
    32→import ids.messaging.core.daps.ConnectorMissingCertExtensionException;
    33→import ids.messaging.core.daps.DapsConnectionException;
    34→import ids.messaging.core.daps.DapsEmptyResponseException;
    35→import ids.messaging.core.daps.TokenManagerService;
    36→import io.jsonwebtoken.JwtBuilder;
    37→import io.jsonwebtoken.Jwts;
    38→import io.jsonwebtoken.SignatureAlgorithm;
    39→import lombok.RequiredArgsConstructor;
    40→import lombok.extern.slf4j.Slf4j;
    41→import okhttp3.FormBody;
    42→import okhttp3.OkHttpClient;
    43→import okhttp3.Request;
    44→import okhttp3.Response;
    45→import okhttp3.ResponseBody;
    46→import org.jetbrains.annotations.NotNull;
    47→import org.json.JSONObject;
    48→import org.springframework.beans.factory.annotation.Value;
    49→import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
    50→import org.springframework.stereotype.Component;
    51→
    52→/**
    53→ * Manages DAT requests to the DAPS.
    54→ */
    55→@Slf4j
    56→@Component
    57→@RequiredArgsConstructor
    58→@ConditionalOnProperty(prefix = "daps", name = "mode", havingValue = "aisec")
    59→public class AisecTokenManagerService implements TokenManagerService {
    60→    /**
    61→     * Seconds to add to the expiry date.
    62→     */
    63→    public static final int ONE_DAY_IN_SECONDS  = 86_400;
    64→
    65→    /**
    66→     * Default offset to be used for DAPS and Connector nbf and issued at dates.
    67→     * Must also be declared here for special use cases.
    68→     */
    69→    public static final int DEFAULT_TIME_OFFSET = 10;
    70→
    71→    /**
    72→     * Seconds to subtract for the issued at and not before in the JWT to the DAPS.
    73→     */
    74→    @Value("#{new Integer('${daps.time.offset.seconds:10}')}")
    75→    private Integer offset;
    76→
    77→    /**
    78→     * The ClientProvider.
    79→     */
    80→    private final ClientProvider  clientProvider;
    81→
    82→    /**
    83→     * The ConfigContainer.
    84→     */
    85→    private final ConfigContainer configContainer;
    86→
    87→    /**
    88→     * Used to switch logging the DAPS response on and off.
    89→     */
    90→    @Value("#{new Boolean('${daps.enable.log.jwt:false}')}")
    91→    private Boolean logDapsResponse;
    92→
    93→    /**
    94→     * SinatureAlgorithm used for signing JWT for DAT request.
    95→     * Supported: RSA256, ECDSA256
    96→     */
    97→    @Value("${daps.jwt.signature.algorithm:RSA256}")
    98→    private String signatureAlgorithm;
    99→
   100→    /**
   101→     * Get the DAT from the DAPS at dapsURL using the current configuration.
   102→     *
   103→     * @param dapsUrl The URL of a DAPS Service
   104→     * @return signed DAPS JWT token for the Connector
   105→     */
   106→    @Override
   107→    public String acquireToken(final String dapsUrl)
   108→            throws
   109→            DapsConnectionException,
   110→            DapsEmptyResponseException,
   111→            ConnectorMissingCertExtensionException {
   112→
   113→        final var keyStoreManager = configContainer.getKeyStoreManager();
   114→        final var targetAudience = "idsc:IDS_CONNECTORS_ALL";
   115→
   116→        var dynamicAttributeToken = "INVALID_TOKEN";
   117→
   118→        // Try clause for setup phase (loading keys, building trust manager)
   119→        try {
   120→            validateCertExpiration(keyStoreManager);
   121→
   122→            final var privateKey = getPrivateKey(keyStoreManager);
   123→
   124→            //aki/ski fingerprint of the connector
   125→            final var fingerprint = ConnectorFingerprintProvider.fingerprint;
   126→            if (fingerprint.isEmpty()) {
   127→                throw new ConnectorMissingCertExtensionException("No fingerprint available!");
   128→            }
   129→            final var connectorFingerprint = fingerprint.get();
   130→
   131→            if (log.isDebugEnabled()) {
   132→                log.debug("Retrieving Dynamic Attribute Token from DAPS... [code=(IMSCOD0104)]");
   133→            }
   134→
   135→            final var jws = getRequestToken(targetAudience, privateKey, connectorFingerprint);
   136→
   137→            // build form body to embed client assertion into post request
   138→            final var formBody = getFormBody(jws);
   139→
   140→            if (log.isDebugEnabled()) {
   141→                log.debug("Getting client... [code=(IMSCOD0105)]");
   142→            }
   143→
   144→            final var client = clientProvider.getClient();
   145→
   146→            if (log.isDebugEnabled()) {
   147→                log.debug("Sending DAT request to DAPS. [code=(IMSCOD0106), url=({})]", dapsUrl);
   148→            }
   149→            final var request = new Request.Builder().url(dapsUrl).post(formBody).build();
   150→
   151→            final var jwtResponse = sendRequestToDAPS(client, request);
   152→            final var responseBody = jwtResponse.body();
   153→            checkEmptyDAPSResponse(responseBody); //can throw exception
   154→
   155→            final var jwtString = responseBody.string();
   156→            dynamicAttributeToken = getDAT(jwtString);
   157→
   158→            if (jwtResponse.isSuccessful() && log.isInfoEnabled()) {
   159→                if (logDapsResponse) {
   160→                    log.info("Successfully received DAT from DAPS."
   161→                            + " [response=({}), code=(IMSCOI0053)]", jwtString);
   162→                } else {
   163→                    log.info("Successfully received DAT from DAPS. [code=(IMSCOI0054)]");
   164→                }
   165→            }
   166→        } catch (IOException e) {
   167→            handleIOException(e);
   168→        } catch (DapsEmptyResponseException e) {
   169→            handleDapsEmptyResponseException(e);
   170→        } catch (ConnectorMissingCertExtensionException e) {
   171→            handleConnectorMissingCertExtensionException();
   172→        }
   173→
   174→        return dynamicAttributeToken;
   175→    }
   176→
   177→    private static void validateCertExpiration(final KeyStoreManager keyStoreManager) {
   178→        final var certExpiration = keyStoreManager.getCertExpiration();
   179→
   180→        if (log.isDebugEnabled()) {
   181→            log.debug("Certificate expiration: ({}) ... [code=(IMSCOI0152)]", certExpiration);
   182→        }
   183→
   184→        if (log.isWarnEnabled()) {
   185→            if (certExpiration.before(new Date())) {
   186→                log.warn("Certificate expired! [code=(IMSCOI0153), date=({})]", certExpiration);
   187→            }
   188→        }
   189→    }
   190→
   191→    /**
   192→     * Handle exception if AKI or SKI of Certificate are not valid or missing.
   193→     *
   194→     * @throws ConnectorMissingCertExtensionException forwarded to the
   195→     * connector developer if AKI or SKI of Certificate are not
   196→     * valid or missing
   197→     */
   198→    private void handleConnectorMissingCertExtensionException()
   199→            throws ConnectorMissingCertExtensionException {
   200→        final var error = "Mandatory required information of the connector "
   201→          + "certificate is missing (AKI/SKI)!"
   202→          + " Needed to determine the fingerprint of the connector for the DAPS!"
   203→          + " Possible reason: Are you using a valid connector certificate issued by the DAPS?";
   204→
   205→        if (configContainer.getConfigurationModel().getConnectorDeployMode()
   206→           != ConnectorDeployMode.TEST_DEPLOYMENT) {
   207→            printProductiveDeploymentError(error);
   208→            throw new ConnectorMissingCertExtensionException(error);
   209→        } else {
   210→            printTestDeploymentWarning(error);
   211→        }
   212→    }
   213→
   214→    /**
   215→     * Handle exception if DAPS returned an empty response.
   216→     *
   217→     * @param e the thrown exception
   218→     * @throws DapsEmptyResponseException forwarded exception to the connector
   219→     * developer if DAPS returned an empty response
   220→     */
   221→    private void handleDapsEmptyResponseException(
   222→            final DapsEmptyResponseException e)
   223→            throws DapsEmptyResponseException {
   224→        final var error = String.format("Unusable answer from DAPS: Possible "
   225→            + "empty DAPS-Response, something went wrong at DAPS: %s",
   226→            e.getMessage());
   227→
   228→        if (configContainer.getConfigurationModel().getConnectorDeployMode()
   229→           != ConnectorDeployMode.TEST_DEPLOYMENT) {
   230→            printProductiveDeploymentError(error);
   231→            throw new DapsEmptyResponseException(error);
   232→        } else {
   233→            printTestDeploymentWarning(error);
   234→        }
   235→    }
   236→
   237→    /**
   238→     * Handle exception if connection to DAPS failed.
   239→     *
   240→     * @param e the thrown IOException
   241→     * @throws DapsConnectionException mapped exception, thrown if connection to DAPS failed
   242→     */
   243→    private void handleIOException(final IOException e) throws DapsConnectionException {
   244→        final var error = String.format("Error connecting to DAPS "
   245→            + "(possibly currently not reachable or wrong DAPS-URL): %s",
   246→            e.getMessage());
   247→
   248→        if (configContainer.getConfigurationModel().getConnectorDeployMode()
   249→           != ConnectorDeployMode.TEST_DEPLOYMENT) {
   250→            printProductiveDeploymentError(error);
   251→            throw new DapsConnectionException(error);
   252→        } else {
   253→            printTestDeploymentWarning(error);
   254→        }
   255→    }
   256→
   257→    private void printTestDeploymentWarning(final String error) {
   258→        if (log.isWarnEnabled()) {
   259→            log.warn(
   260→                    "TEST_DEPLOYMENT: IDS-Message is sent without a valid DAT, "
   261→                    + "will not be sent in PRODUCTIVE_DEPLOYMENT. [code=(IMSCOW0041),"
   262→                    + " reason=({})]", error);
   263→        }
   264→    }
   265→
   266→    private void printProductiveDeploymentError(final String error) {
   267→        if (log.isErrorEnabled()) {
   268→            log.error(
   269→                    "PRODUCTIVE_DEPLOYMENT: No IDS-Message sent! "
   270→                    + "No DAT could be acquired from DAPS! [code=(IMSCOE0001),"
   271→                    + " reason=({})]", error);
   272→        }
   273→    }
   274→
   275→    /**
   276→     * Get the DAT of the response from DAPS.
   277→     *
   278→     * @param jwtString the DAPS response
   279→     * @return the DAT
   280→     */
   281→    private String getDAT(final String jwtString) {
   282→        final var jsonObject = new JSONObject(jwtString);
   283→        return jsonObject.getString("access_token");
   284→    }
   285→
   286→    /**
   287→     * DAPS didn't return a response.
   288→     *
   289→     * @param responseBody the response of the DAPS to be checked
   290→     * @throws DapsEmptyResponseException thrown if response of DAPS is empty
   291→     */
   292→    private void checkEmptyDAPSResponse(final ResponseBody responseBody)
   293→            throws DapsEmptyResponseException {
   294→        if (responseBody == null) {
   295→            throw new DapsEmptyResponseException("JWT response is null.");
   296→        }
   297→    }
   298→
   299→    /**
   300→     * Sends the request for a DAT to the DAPS.
   301→     *
   302→     * @param client  the HTTP-Client used for sending messages
   303→     * @param request the request-message to be send
   304→     * @return the response of the DAPS
   305→     * @throws IOException thrown if something went wrong connecting to the DAPS
   306→     */
   307→    @NotNull
   308→    private Response sendRequestToDAPS(final OkHttpClient client,
   309→                                       final Request request)
   310→            throws IOException {
   311→        final var jwtResponse = client.newCall(request).execute();
   312→
   313→        if (!jwtResponse.isSuccessful()) {
   314→            if (log.isDebugEnabled()) {
   315→                log.debug("DAPS request was not successful! [code=(IMSCOD0107)]");
   316→            }
   317→
   318→            final var responseBody = jwtResponse.body();
   319→            final var bodyString = responseBody == null ? "" : " Body: " + responseBody.string();
   320→            throw new IOException("Unexpected code " + jwtResponse + bodyString);
   321→        }
   322→        return jwtResponse;
   323→    }
   324→
   325→    /**
   326→     * Get the form body for the DAPS-Request.
   327→     *
   328→     * @param jws the generated JWS
   329→     * @return The Request-Formbody
   330→     */
   331→    @NotNull
   332→    private FormBody getFormBody(final String jws) {
   333→        return new FormBody.Builder()
   334→                .add("grant_type", "client_credentials")
   335→                .add("client_assertion_type",
   336→                     "urn:ietf:params:oauth:client-assertion-type:jwt-bearer")
   337→                .add("client_assertion", jws)
   338→                .add("scope", "idsc:IDS_CONNECTOR_ATTRIBUTES_ALL")
   339→                .build();
   340→    }
   341→
   342→    /**
   343→     * Get the signed(!) request token.
   344→     *
   345→     * @param targetAudience The target audience.
   346→     * @param privateKey The private key of the keystore.
   347→     * @param connectorFingerprint The fingerprint of the Connector (UID).
   348→     * @return The signed request token.
   349→     */
   350→    private String getRequestToken(final String targetAudience,
   351→                                   final PrivateKey privateKey,
   352→                                   final String connectorFingerprint) {
   353→        if (log.isDebugEnabled()) {
   354→            log.debug("Building jwt token... [code=(IMSCOD0108)]");
   355→        }
   356→
   357→        final var expiryDate = Date.from(Instant.now().plusSeconds(ONE_DAY_IN_SECONDS));
   358→        final var jwtb = getJwtBuilder(targetAudience, connectorFingerprint, expiryDate);
   359→
   360→        if (log.isDebugEnabled()) {
   361→            log.debug("Signing jwt token... [code=(IMSCOD0109)]");
   362→        }
   363→
   364→        if ("ECDSA256".equals(signatureAlgorithm)) {
   365→            // ECDSA 256
   366→            return jwtb.signWith(SignatureAlgorithm.ES256, privateKey).compact();
   367→        } else {
   368→            // Default: RSA 256
   369→            return jwtb.signWith(SignatureAlgorithm.RS256, privateKey).compact();
   370→        }
   371→    }
   372→
   373→    /**
   374→     * Get the JWT Builder.
   375→     *
   376→     * @param targetAudience The targetAudience.
   377→     * @param connectorFingerprint The fingerprint of the Connector (UID).
   378→     * @param expiryDate The set expiry date.
   379→     * @return The JWT-Builder.
   380→     */
   381→    private JwtBuilder getJwtBuilder(final String targetAudience,
   382→                                     final String connectorFingerprint,
   383→                                     final Date expiryDate) {
   384→
   385→        if (offset == null) {
   386→            offset = DEFAULT_TIME_OFFSET;
   387→        }
   388→
   389→        if (log.isDebugEnabled()) {
   390→            log.debug("JWT for DAPS request: using offset seconds for issuedAt and notBefore"
   391→                      + " [offset=({}), code=(IMSCOD0143)]", offset);
   392→        }
   393→
   394→        final var timeWithOffset = Date.from(Instant.now().minusSeconds(offset));
   395→
   396→        return Jwts.builder()
   397→                   .setIssuer(connectorFingerprint)
   398→                   .setSubject(connectorFingerprint)
   399→                   .claim("@context", "https://w3id.org/idsa/contexts/context.jsonld")
   400→                   .claim("@type", "ids:DatRequestToken")
   401→                   .setExpiration(expiryDate)
   402→                   .setIssuedAt(timeWithOffset)
   403→                   .setAudience(targetAudience)
   404→                   .setNotBefore(timeWithOffset);
   405→    }
   406→
   407→    /**
   408→     * Getting PrivateKey from KeyStoreManager.
   409→     *
   410→     * @param keyStoreManager The KeyStoreManager holding the PrivateKey
   411→     * @return The PrivateKey of the KeyStoreManager
   412→     */
   413→    private PrivateKey getPrivateKey(final KeyStoreManager keyStoreManager) {
   414→        if (log.isDebugEnabled()) {
   415→            log.debug("Getting PrivateKey from KeyStoreManager... [code=(IMSCOD0113)]");
   416→        }
   417→
   418→        return keyStoreManager.getPrivateKey();
   419→    }
   420→}
   421→

