    59→import org.bouncycastle.operator.jcajce.JcaContentSignerBuilder;
    60→import org.bouncycastle.pkcs.PKCS10CertificationRequest;
    61→import org.bouncycastle.pkcs.jcajce.JcaPKCS10CertificationRequestBuilder;
    62→import org.bouncycastle.util.io.pem.PemObject;
    63→import org.bouncycastle.util.io.pem.PemWriter;
    64→import org.json.JSONObject;
    65→import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
    66→import org.springframework.stereotype.Component;
    67→
    68→/**
    69→ * Manages Dynamic Attribute Tokens.
    70→ */
    71→@Slf4j
    72→@Component
    73→@RequiredArgsConstructor
    74→@ConditionalOnProperty(prefix = "daps", name = "mode", havingValue = "orbiter")
    75→public class OrbiterTokenManagerService implements TokenManagerService {
    76→
    77→    /**
    78→     * The chosen keysize.
    79→     */
    80→    public static final int KEYSIZE = 2048;
    81→
    82→    /**
    83→     * Seconds to subtract for issued at to avoid time problems.
    84→     */
    85→    public static final int SECONDS_TO_SUBTRACT = 10;
    86→
    87→    /**
    88→     * The default client registration URL.
    89→     */
    90→    private static final String CLIENT_REGISTRATION_URL
    91→        = "https://orbiter-daps-staging.truzzt.org/api/client/create";
    92→
    93→    /**
    94→     * Used for reading all necessary bytes of the response.
    95→     */
    96→    private static final int BYTESINT = 0xFF;
    97→
    98→    /**
    99→     * The ClientProvider.
   100→     */
   101→    private final ClientProvider clientProvider;
   102→
   103→    /**
   104→     * The certificate.
   105→     */
   106→    private X509Certificate clientCert;
   107→
   108→    /**
   109→     * The generated keypair used.
   110→     */
   111→    private KeyPair generatedKeyPair;
   112→
   113→    /**
   114→     * Client-ID for the request body.
   115→     */
   116→    private String id;
   117→
   118→    /**
   119→     * Create a Client at the Orbiter DAPS, request a DAT and return it.
   120→     */
   121→    public void createClient() {
   122→        final var client = clientProvider.getClient();
   123→        try {
   124→            setKeyPair();
   125→
   126→            final var csr = createCSR();
   127→
   128→            //write csr to string
   129→            final var csrString = getCertificateRequest(csr);
   130→
   131→            //build request
   132→            final var request = getCertificateRequestMessage(csrString);
   133→
   134→            //parse client response
   135→            final var dapsResponse = sendCertificateRequest(client, request);
   136→
   137→            final var responseJson = new JSONObject(dapsResponse);
   138→
   139→            setClientId(responseJson);
   140→            setClientCertificate(responseJson);
   141→
   142→        } catch (NoSuchAlgorithmException
   143→                | OperatorCreationException
   144→                | IOException
   145→                | CertificateException e) {
   146→            if (log.isWarnEnabled()) {
   147→                log.warn("[code=(IMSCOW0028)] " + e.getMessage(), e);
   148→            }
   149→        }
   150→    }
   151→
   152→    private void setClientCertificate(final JSONObject responseJson)
   153→            throws CertificateException {
   154→        final var responseCert = responseJson.getJSONObject("cert");
   155→        final var responseData = responseCert.getJSONArray("data");
   156→        var bytes = new byte[responseData.length()];
   157→
   158→        for (var i = 0; i < responseData.length(); i++) {
   159→            bytes[i] = (byte) (((int) responseData.get(i)) & BYTESINT);
   160→        }
   161→
   162→        final var certFactory = CertificateFactory.getInstance("X.509");
   163→        final var in = new ByteArrayInputStream(bytes);
   164→
   165→        clientCert = (X509Certificate) certFactory.generateCertificate(in);
   166→    }
   167→
   168→    private void setClientId(final JSONObject responseJson) {
   169→        id = responseJson.getString("id");
   170→    }
   171→
   172→    private String sendCertificateRequest(final OkHttpClient client,
   173→                                          final Request request)
   174→            throws IOException {
   175→        final var response = client.newCall(request).execute();
   176→
   177→        return Objects.requireNonNull(response.body()).string();
   178→    }
   179→
   180→    private Request getCertificateRequestMessage(final String csrString) {
   181→        final var clientToCreate = new JSONObject();
   182→        clientToCreate.put("grants", List.of("client_assertion_type"));
   183→        clientToCreate.put("pkcs10Data", csrString);
   184→        clientToCreate.put("userId", "TEST");
   185→
   186→        return new Request.Builder()
   187→                .url(CLIENT_REGISTRATION_URL)
   188→                .post(RequestBody.create(clientToCreate.toString(),
   189→                                         MediaType.parse("application/json")))
   190→                .build();
   191→    }
   192→
   193→    private String getCertificateRequest(final PKCS10CertificationRequest csr)
   194→            throws IOException {
   195→        final var pemObject = new PemObject("CERTIFICATE REQUEST", csr.getEncoded());
   196→        final var stringWriter = new StringWriter();
   197→
   198→        final var pemWriter = new PemWriter(stringWriter);
   199→        pemWriter.writeObject(pemObject);
   200→        pemWriter.close();
   201→        stringWriter.close();
   202→
   203→        return stringWriter.toString();
   204→    }
   205→
   206→    private void setKeyPair() throws NoSuchAlgorithmException {
   207→        final var keyPairGenerator =
   208→                KeyPairGenerator.getInstance("RSA", new BouncyCastleProvider());
   209→        keyPairGenerator.initialize(KEYSIZE, new SecureRandom());
   210→
   211→        generatedKeyPair = keyPairGenerator.generateKeyPair();
   212→    }
   213→
   214→    /**
   215→     * Generate a CSR which is sent to the Orbiter DAPS to register a Client.
   216→     *
   217→     * @return a generated CSR
   218→     * @throws OperatorCreationException when the ContentSigner
   219→     * cannot be created
   220→     * @throws IOException when the Extensions cannot be added to the CSR
   221→     */
   222→    private PKCS10CertificationRequest createCSR()
   223→            throws IOException, OperatorCreationException {
   224→        //create csr builder with principal
   225→        final var p10Builder = new JcaPKCS10CertificationRequestBuilder(
   226→                new X500Principal("C=DE, ST=Bonn, L=NRW, O=truzzt, CN=*.truzzt.org"),
   227→                         generatedKeyPair.getPublic());
   228→
   229→        //add extensions
   230→        final var extensionsGenerator = new ExtensionsGenerator();
   231→
   232→        //basic constraints = false
   233→        extensionsGenerator.addExtension(Extension.basicConstraints, false,
   234→                                         new BasicConstraints(false));
   235→
   236→        //add subject alternative names
   237→        final var sans = new ASN1Encodable[]{
   238→                new GeneralName(GeneralName.dNSName, "*.truzzt.org"),
   239→                new GeneralName(GeneralName.dNSName, "*.truzzt.com")
   240→        };
   241→
   242→        final var sansExtension = new DERSequence(sans);
   243→        extensionsGenerator
   244→                .addExtension(Extension.subjectAlternativeName,
   245→                              false,
   246→                              sansExtension);
   247→
   248→        //TODO add SKI extension but currently working without it)
   249→        //extensionsGenerator.addExtension(Extension.subjectKeyIdentifier,
   250→        // true, new SubjectKeyIdentifier());
   251→
   252→        final var extensions = extensionsGenerator.generate();
   253→        p10Builder.addAttribute(
   254→                PKCSObjectIdentifiers.pkcs_9_at_extensionRequest,
   255→                extensions);
   256→
   257→        //create csBuilder for signing the request
   258→        final var csBuilder = new JcaContentSignerBuilder("SHA256withRSA");
   259→        final var signer = csBuilder.build(generatedKeyPair.getPrivate());
   260→
   261→        //build and return the csr
   262→        return p10Builder.build(signer);
   263→    }
   264→
   265→    /**
   266→     * Get the DAT Token from Orbiter DAPS.
   267→     *
   268→     * @param dapsUrl The URL of the DAPS
   269→     * @return access jwt token as String
   270→     */
   271→    @Override
   272→    public String acquireToken(final String dapsUrl) {
   273→        final var client = clientProvider.getClient();
   274→
   275→        //register at Orbiter DAPS if this is called the first time
   276→        if (id == null || generatedKeyPair == null || clientCert == null) {
   277→            //does this have to happen in the framework or should we expect
   278→            // a keystore provided by the user (like Aisec Daps Client)
   279→            createClient();
   280→        }
   281→
   282→        final var token = getRequestToken();
   283→        final var formBody = getRequestBody(token);
   284→        final var request = getRequestMessage(dapsUrl, formBody);
   285→
   286→        try {
   287→            return getDAT(client, request);
   288→        } catch (IOException e) {
   289→            if (log.isWarnEnabled()) {
   290→                log.warn("[code=(IMSCOW0029)] " + e.getMessage(), e);
   291→            }
   292→
   293→            return "";
   294→        }
   295→    }
   296→
   297→    private String getDAT(
   298→            final OkHttpClient client,
   299→            final Request request)
   300→            throws IOException {
   301→        final var jwtResponse = client.newCall(request).execute();
   302→        final var responseJson = new JSONObject(
   303→                Objects.requireNonNull(jwtResponse.body()).string());
   304→
   305→        return responseJson.getString("accessToken");
   306→    }
   307→
   308→    private Request getRequestMessage(final String dapsUrl,
   309→                                      final RequestBody formBody) {
   310→        return new Request.Builder()
   311→                .url(dapsUrl)
   312→                .post(formBody)
   313→                .build();
   314→    }
   315→
   316→    private RequestBody getRequestBody(final String token) {
   317→        return new FormBody.Builder()
   318→                .add("grant_type", "client_assertion_type")
   319→                .add("client_assertion_type",
   320→                     "urn:ietf:params:oauth:client-assertion-type:jwt-bearer")
   321→                .add("client_assertion", token)
   322→                .add("scope", "idsc:IDS_CONNECTOR_ATTRIBUTES_ALL")
   323→                .add("client_id", id)
   324→                .build();
   325→    }
   326→
   327→    private String getRequestToken() {
   328→        final var jwtb =
   329→                Jwts.builder()
   330→                    .setIssuer("localhost")
   331→                    .setSubject(id)
   332→                    .claim("@context",
   333→                           "https://w3id.org/idsa/contexts/context.jsonld")
   334→                    .claim("@type", "ids:DatRequestToken")
   335→                    .setExpiration(
   336→                            Date.from(Instant.now().plus(Duration.ofDays(1))))
   337→                    .setAudience("all")
   338→                    .setIssuedAt(Date.from(
   339→                            Instant.now().minusSeconds(SECONDS_TO_SUBTRACT)))
   340→                    .setNotBefore(Date.from(
   341→                            Instant.now().minusSeconds(SECONDS_TO_SUBTRACT)));
   342→
   343→        return jwtb.signWith(SignatureAlgorithm.RS256,
   344→                             generatedKeyPair.getPrivate()).compact();
   345→    }
   346→}
   347→

