   213→                if (log.isWarnEnabled()) {
   214→                    log.warn(String.format(
   215→                            "No key found at DAPS url, kid combination %s:%s!", pubKeysUrl, kid)
   216→                    );
   217→                }
   218→                if (log.isWarnEnabled()) {
   219→                    log.warn("No public key for DAPS was found for DAT to verify claims!"
   220→                             + " [code=(IMSCOW0147), url=[{}], kid=({})]", pubKeysUrl, kid);
   221→                }
   222→                return null;
   223→            }
   224→        } catch (Exception e) {
   225→            if (log.isErrorEnabled()) {
   226→                log.error("Exception while requesting public key from token issuer!"
   227→                          + " [code=(IMSCOE0148), message=[{}]]", e.getMessage());
   228→            }
   229→            return null;
   230→        }
   231→    }
   232→
   233→    /**
   234→     * @return True if jwt expired.
   235→     */
   236→    private boolean isExpired() {
   237→        final var expired = expiration == null
   238→                || expiration.before(Date.from(Instant.now().plusSeconds(EXPIRATION_LEEWAY)));
   239→
   240→        if (currentJwt != null) {
   241→            //Will only log if DAT was successfully acquired.
   242→            if (expired && log.isInfoEnabled()) {
   243→                log.info("Cached DAPS DAT expired or no expiration set."
   244→                                + " [expiration=({}), code=(IMSCOI0052)]",
   245→                         expiration);
   246→            } else if (log.isInfoEnabled()) {
   247→                log.info("Using cached DAPS DAT. [expiration=({}), code=(IMSCOI0053)]",
   248→                         expiration);
   249→            }
   250→        }
   251→
   252→        return expired;
   253→    }
   254→}
