    45→     * The DapsPublicKeyProvider.
    46→     */
    47→    private final DapsPublicKeyProvider keyProvider;
    48→
    49→    /**
    50→     * Includes base certificates.
    51→     */
    52→    private final String[] baseSecProfVals =
    53→            {"idsc:BASE_CONNECTOR_SECURITY_PROFILE",
    54→            "idsc:BASE_SECURITY_PROFILE"};
    55→
    56→    /**
    57→     * Includes all certificates up to trust.
    58→     */
    59→    private final String[] trustSecProfVals =
    60→            {"idsc:BASE_CONNECTOR_SECURITY_PROFILE",
    61→            "idsc:BASE_SECURITY_PROFILE",
    62→            "idsc:TRUST_SECURITY_PROFILE",
    63→            "idsc:TRUSTED_CONNECTOR_SECURITY_PROFILE"};
    64→
    65→    /**
    66→     * Includes all certificates up to trust plus.
    67→     */
    68→    private final String[] plusTrustSecProfVals =
    69→            {"idsc:BASE_CONNECTOR_SECURITY_PROFILE",
    70→            "idsc:BASE_SECURITY_PROFILE",
    71→            "idsc:TRUST_SECURITY_PROFILE",
    72→            "idsc:TRUSTED_CONNECTOR_SECURITY_PROFILE",
    73→            "idsc:TRUST_PLUS_SECURITY_PROFILE",
    74→            "idsc:TRUSTED_CONNECTOR_PLUS_SECURITY_PROFILE"};
    75→
    76→    /**
    77→     * Extract the Claims from the Dat token of a message, given the Message and a publicKey.
    78→     *
    79→     * @param token {@link DynamicAttributeToken} of an incoming RequestMessage.
    80→     * @param publicKey The public Key.
    81→     * @return The Claims of the messages DAT Token, when it can be signed with the given key.
    82→     * @throws ClaimsException If Token cannot be signed with the given key.
    83→     */
