   116→        final var claim = Jwts.parser().parseClaimsJwt(noSigJwt);
   117→
   118→        //read kid and issuer of token content and request public key from issuer using the kid
   119→        final var key = keyProvider.requestPublicKey(
   120→                claim.getBody().getIssuer(),
   121→                claim.getHeader().get("kid").toString());
   122→
   123→        //get claims from token using token and requested public key of issuer
   124→        //(and validate the token using the public key as signingKey in parser)
   125→        return getClaims(token, key);
   126→    }
   127→
   128→    /**
   129→     * Check the claims of the DAT.
   130→     *
   131→     * @param claims JWS claims of DAT Token.
   132→     * @param extraAttributes Extra attributes to be checked.
   133→     * @return True, if claims are valid.
   134→     */
   135→    public boolean checkClaims(final Jws<Claims> claims,
   136→                               final Map<String, Object> extraAttributes) {
   137→        if (extraAttributes != null && extraAttributes.containsKey("securityProfile")) {
   138→            try {
   139→                verifySecurityProfile(claims.getBody().get("securityProfile", String.class),
   140→                        extraAttributes.get("securityProfile").toString());
   141→            } catch (ClaimsException e) {
   142→                if (log.isWarnEnabled()) {
   143→                    log.warn("SecurityProfile could not be successfully verified!"
   144→                             + " [message=({}), code=(IMSCOW0033)]", e.getMessage());
   145→                }
   146→                return false;
   147→            }
   148→        }
   149→        try {
   150→            return DapsVerifier.verify(claims);
   151→        } catch (ClaimsException e) {
   152→            if (log.isWarnEnabled()) {
   153→                log.warn("Claims could not be successfully verified! [message=({}),"
   154→                         + " code=(IMSCOW0034)]", e.getMessage());
   155→            }
   156→            return false;
   157→        }
   158→    }
   159→
   160→    /**
   161→     * Check a given DAT considering additional attributes from the message payload.
   162→     *
   163→     * @param token {@link DynamicAttributeToken} of an incoming Message.
   164→     * @param extraAttributes Additional Attributes from the Message Payload.
   165→     * @return True if DAT is valid.
   166→     */
   167→    public boolean checkDat(final DynamicAttributeToken token,
   168→                            final Map<String, Object> extraAttributes) {
   169→        Jws<Claims> claims;
   170→        try {
   171→            claims = getClaims(token);
   172→        } catch (ClaimsException | ExpiredJwtException e) {
   173→            return false;
   174→        }
   175→        if (claims == null) {
   176→            return false;
   177→        }
   178→
   179→        return checkClaims(claims, extraAttributes);
   180→    }
   181→
   182→    /**
   183→     * Check a given DAT.
   184→     *
   185→     * @param token A {@link DynamicAttributeToken} from a Infomodel Message.
   186→     * @return True if DAT is valid.
   187→     */
   188→    public boolean checkDat(final DynamicAttributeToken token) {
   189→        return checkDat(token, null);
   190→    }
   191→
   192→    /**
   193→     * Verifies that the {@link de.fraunhofer.iais.eis.SecurityProfile}
   194→     * in the token is  same as in the Selfdescription.
   195→     *
   196→     * @param registered The SecurityProfile ID  in token.
   197→     * @param given The SecurityProfile ID in Selfdescription.
   198→     * @throws ClaimsException If SecurityProfiles do not match.
   199→     */
   200→    private void verifySecurityProfile(final String registered,
   201→                                       final String given)
   202→            throws ClaimsException {
   203→        if (registered == null) {
   204→            throw new ClaimsException("Security profile violation."
   205→                                      + " No security profile given in DAT!");
   206→        }
   207→
   208→        final var adjustedRegistered = registered.replace("https://w3id.org/idsa/code/", "idsc:");
   209→        final var adjustedGiven = given.replace("https://w3id.org/idsa/code/", "idsc:");
   210→
   211→        String[] includedProfiles;
   212→        switch (adjustedRegistered) {
   213→            case "idsc:BASE_CONNECTOR_SECURITY_PROFILE":
   214→            case "idsc:BASE_SECURITY_PROFILE":
   215→                includedProfiles = baseSecProfVals;
   216→                break;
   217→            case "idsc:TRUST_SECURITY_PROFILE":
   218→            case "idsc:TRUSTED_CONNECTOR_SECURITY_PROFILE":
   219→                includedProfiles = trustSecProfVals;
   220→                break;
   221→            case "idsc:TRUST_PLUS_SECURITY_PROFILE":
   222→            case "idsc:TRUSTED_CONNECTOR_PLUS_SECURITY_PROFILE":
   223→                includedProfiles = plusTrustSecProfVals;
   224→                break;
   225→            default:
   226→                includedProfiles = new String[0];
   227→        }
   228→
   229→        if (!Arrays.asList(includedProfiles).contains(adjustedGiven)) {
   230→            throw new ClaimsException(
   231→                    "Security profile violation. Registered security profile"
   232→                    + " at DAPS is: " + registered
   233→                    + ", but the given security profile is: " + given);
   234→        }
   235→    }
